{"explanation":"The vertex form y = a(x − h)² + k makes transformations easy to read: h shifts the parabola left/right, k shifts it up/down, and a controls vertical stretch/compression and whether it opens up (a > 0) or down (a < 0). The vertex sits at the point (h, k). Use the sliders to change a, h, and k and watch the graph and vertex move in real time.","manimCode":"const axes = new Axes({
  xRange: [-6, 6, 1],
  yRange: [-4, 4, 1],
  xLength: 11,
  yLength: 6.5,
  tips: true
});

let a = 1;
let h = 0;
let k = 0;

let curve = axes.plot(x => a * (x - h) * (x - h) + k, {
  color: BLUE,
  xRange: [-6, 6],
  numSamples: 400
});

const vertex = new Dot({ point: axes.c2p(h, k), color: YELLOW });

let eq = new MathTex({ latex: 'y = 1(x - 0)^{2} + 0', color: WHITE });
await eq.waitForRender();
eq.toCorner(UL);
eq.shift(scaleVec(0.3, DOWN));
eq.shift(scaleVec(0.2, RIGHT));

const vertexLabel = new Text({ text: 'vertex (h, k)', color: YELLOW, fontSize: 22 });
vertexLabel.nextTo(vertex, UR);

scene.add(axes, curve, vertex, eq, vertexLabel);

function formatNum(n) {
  const r = Math.round(n * 100) / 100;
  return Number.isInteger(r) ? String(r) : r.toFixed(2);
}

function updateEquation() {
  const pos = eq.getCenter();
  scene.remove(eq);
  const aStr = formatNum(a);
  const hStr = formatNum(h);
  const kStr = formatNum(k);
  const hPart = h >= 0 ? `(x - ${hStr})` : `(x + ${formatNum(-h)})`;
  const kPart = k >= 0 ? `+ ${kStr}` : `- ${formatNum(-k)}`;
  eq = new MathTex({ latex: `y = ${aStr}${hPart}^{2} ${kPart}`, color: WHITE });
  // waitForRender is async; fire-and-forget then place
  eq.waitForRender().then(() => {
    eq.moveTo(pos);
  });
  scene.add(eq);
}

function rebuild() {
  scene.remove(curve);
  curve = axes.plot(x => a * (x - h) * (x - h) + k, {
    color: a >= 0 ? BLUE : RED,
    xRange: [-6, 6],
    numSamples: 400
  });
  scene.add(curve);
  vertex.moveTo(axes.c2p(h, k));
  vertexLabel.nextTo(vertex, UR);
  updateEquation();
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });

controls.addSlider({
  label: 'a (stretch / flip)',
  min: -3,
  max: 3,
  value: 1,
  step: 0.1,
  onChange: (val) => {
    a = val === 0 ? 0.01 : val;
    rebuild();
  }
});

controls.addSlider({
  label: 'h (horizontal shift)',
  min: -4,
  max: 4,
  value: 0,
  step: 0.1,
  onChange: (val) => {
    h = val;
    rebuild();
  }
});

controls.addSlider({
  label: 'k (vertical shift)',
  min: -3,
  max: 3,
  value: 0,
  step: 0.1,
  onChange: (val) => {
    k = val;
    rebuild();
  }
});

controls.addButton({
  label: 'Reset',
  onClick: () => {
    a = 1;
    h = 0;
    k = 0;
    rebuild();
  }
});

await scene.wait(999999);"}

